class Solution {
    public int nextGreaterElement(int n) {
        char[] s = Integer.toString(n).toCharArray();
        int len = s.length;
        int i = len - 2;
        while (i >= 0 && s[i] >= s[i + 1]) {
            i--;
        }
        if (i < 0) return -1;
        int j = len - 1;
        while (s[j] <= s[i]) {
            j--;
        }
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
        int left = i + 1, right = len - 1;
        while (left < right) {
            char t = s[left];
            s[left] = s[right];
            s[right] = t;
            left++;
            right--;
        }
        long val = Long.parseLong(new String(s));
        return val <= Integer.MAX_VALUE ? (int) val : -1;
    }
}

var nextGreaterElement = function(n) {
    const s = String(n).split('');
    const len = s.length;
    let i = len - 2;
    while (i >= 0 && s[i] >= s[i + 1]) {
        i--;
    }
    if (i < 0) return -1;
    let j = len - 1;
    while (s[j] <= s[i]) {
        j--;
    }
    [s[i], s[j]] = [s[j], s[i]];
    let left = i + 1, right = len - 1;
    while (left < right) {
        [s[left], s[right]] = [s[right], s[left]];
        left++;
        right--;
    }
    const val = Number(s.join(''));
    return val <= 2147483647 ? val : -1;
};
